(function(){'use strict';const dialog=document.getElementById('aboutDialog'),open=document.getElementById('openAbout'),close=document.querySelector('.about-close'),count=document.getElementById('aboutDataCount');if(!dialog||!open)return;const read=key=>{try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[]}catch(error){return[]}};function update(){const sightings=read('safariPocketbookSightings').length,places=read('safariPocketbookSavedPlaces').length;count.textContent=`On this device: ${sightings} sighting${sightings===1?'':'s'} and ${places} saved place${places===1?'':'s'}.`}open.addEventListener('click',()=>{update();dialog.showModal()});close?.addEventListener('click',()=>dialog.close());document.getElementById('aboutExport')?.addEventListener('click',()=>{dialog.close();document.getElementById('exportJournal')?.click()});document.getElementById('aboutErase')?.addEventListener('click',()=>{dialog.close();document.getElementById('clearJournal')?.click()})})();
